import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type MouseEvent,
  type ReactNode,
} from "react";
import "./LayeredPagination.css";

export type LayeredPaginationTone = "neutral" | "copper" | "green" | "gold";
export type LayeredPaginationSize = "small" | "medium";

export interface LayeredPaginationProps
  extends ComponentPropsWithoutRef<"nav"> {
  tone?: LayeredPaginationTone;
  paginationSize?: LayeredPaginationSize;
}

export const LayeredPagination = forwardRef<
  HTMLElement,
  LayeredPaginationProps
>(function LayeredPagination(
  {
    tone = "neutral",
    paginationSize = "medium",
    className = "",
    "aria-label": ariaLabel = "Pagination",
    ...props
  },
  ref
) {
  return (
    <nav
      {...props}
      ref={ref}
      aria-label={ariaLabel}
      data-tone={tone}
      data-size={paginationSize}
      className={["layered-pagination", className].filter(Boolean).join(" ")}
    />
  );
});

export type LayeredPaginationListProps = ComponentPropsWithoutRef<"ul">;

export const LayeredPaginationList = forwardRef<
  HTMLUListElement,
  LayeredPaginationListProps
>(function LayeredPaginationList({ className = "", ...props }, ref) {
  return (
    <ul
      {...props}
      ref={ref}
      className={["layered-pagination__list", className]
        .filter(Boolean)
        .join(" ")}
    />
  );
});

export type LayeredPaginationItemProps = ComponentPropsWithoutRef<"li">;

export const LayeredPaginationItem = forwardRef<
  HTMLLIElement,
  LayeredPaginationItemProps
>(function LayeredPaginationItem({ className = "", ...props }, ref) {
  return (
    <li
      {...props}
      ref={ref}
      className={["layered-pagination__item", className]
        .filter(Boolean)
        .join(" ")}
    />
  );
});

export interface LayeredPaginationLinkProps
  extends ComponentPropsWithoutRef<"a"> {
  isCurrent?: boolean;
  disabled?: boolean;
}

export const LayeredPaginationLink = forwardRef<
  HTMLAnchorElement,
  LayeredPaginationLinkProps
>(function LayeredPaginationLink(
  {
    isCurrent = false,
    disabled = false,
    className = "",
    href,
    tabIndex,
    onClick,
    "aria-current": ariaCurrent,
    "aria-disabled": ariaDisabled,
    ...props
  },
  ref
) {
  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
    if (disabled) {
      event.preventDefault();
      return;
    }

    onClick?.(event);
  };

  return (
    <a
      {...props}
      ref={ref}
      href={disabled ? undefined : href}
      tabIndex={disabled ? -1 : tabIndex}
      aria-current={isCurrent ? "page" : ariaCurrent}
      aria-disabled={disabled ? true : ariaDisabled}
      data-current={isCurrent ? "true" : undefined}
      data-disabled={disabled ? "true" : undefined}
      onClick={handleClick}
      className={["layered-pagination__link", className]
        .filter(Boolean)
        .join(" ")}
    />
  );
});

export interface LayeredPaginationDirectionProps
  extends Omit<LayeredPaginationLinkProps, "children" | "isCurrent"> {
  children?: ReactNode;
}

export const LayeredPaginationPrevious = forwardRef<
  HTMLAnchorElement,
  LayeredPaginationDirectionProps
>(function LayeredPaginationPrevious(
  {
    children = "Previous",
    className = "",
    "aria-label": ariaLabel = "Previous page",
    ...props
  },
  ref
) {
  return (
    <LayeredPaginationLink
      {...props}
      ref={ref}
      aria-label={ariaLabel}
      className={["layered-pagination__direction", className]
        .filter(Boolean)
        .join(" ")}
    >
      <span
        className="layered-pagination__chevron layered-pagination__chevron--previous"
        aria-hidden="true"
      />
      <span className="layered-pagination__direction-label">{children}</span>
    </LayeredPaginationLink>
  );
});

export const LayeredPaginationNext = forwardRef<
  HTMLAnchorElement,
  LayeredPaginationDirectionProps
>(function LayeredPaginationNext(
  {
    children = "Next",
    className = "",
    "aria-label": ariaLabel = "Next page",
    ...props
  },
  ref
) {
  return (
    <LayeredPaginationLink
      {...props}
      ref={ref}
      aria-label={ariaLabel}
      className={["layered-pagination__direction", className]
        .filter(Boolean)
        .join(" ")}
    >
      <span className="layered-pagination__direction-label">{children}</span>
      <span
        className="layered-pagination__chevron layered-pagination__chevron--next"
        aria-hidden="true"
      />
    </LayeredPaginationLink>
  );
});

export type LayeredPaginationEllipsisProps = ComponentPropsWithoutRef<"span">;

export const LayeredPaginationEllipsis = forwardRef<
  HTMLSpanElement,
  LayeredPaginationEllipsisProps
>(function LayeredPaginationEllipsis(
  { className = "", "aria-hidden": ariaHidden = true, ...props },
  ref
) {
  return (
    <span
      {...props}
      ref={ref}
      aria-hidden={ariaHidden}
      className={["layered-pagination__ellipsis", className]
        .filter(Boolean)
        .join(" ")}
    >
      &hellip;
    </span>
  );
});

.layered-pagination {
    --pagination-tone-light: var(--tone-neutral-light);
    --pagination-tone-mid: var(--tone-neutral-mid);
    --pagination-tone-dark: var(--tone-neutral-dark);
    --pagination-focus: var(--control-focus);
    --pagination-control-size: 32px;
    --pagination-direction-padding: 9px;
    --pagination-font-size: 0.75rem;
    --pagination-gap: 3px;

    box-sizing: border-box;
    display: block;
    width: fit-content;
    max-width: 100%;
    padding: 3px;
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--pagination-tone-light) 18%, var(--control-shell-border));
    border-radius: calc(var(--control-radius-outer) - 2px);
    background:
        linear-gradient(180deg,
            color-mix(in srgb, var(--pagination-tone-light) 5%, var(--control-shell-top)) 0%,
            var(--control-shell-bottom) 100%);
    box-shadow:
        inset 0 1px rgb(255 255 255 / 5%),
        0 1px 3px rgb(0 0 0 / 30%);
}

.layered-pagination[data-size="small"] {
    --pagination-control-size: 28px;
    --pagination-direction-padding: 7px;
    --pagination-font-size: 0.6875rem;
    --pagination-gap: 2px;
}

.layered-pagination[data-tone="copper"] {
    --pagination-tone-light: var(--tone-copper-light);
    --pagination-tone-mid: var(--tone-copper-mid);
    --pagination-tone-dark: var(--tone-copper-dark);
    --pagination-focus: var(--tone-copper-light);
}

.layered-pagination[data-tone="green"] {
    --pagination-tone-light: var(--tone-green-light);
    --pagination-tone-mid: var(--tone-green-mid);
    --pagination-tone-dark: var(--tone-green-dark);
    --pagination-focus: var(--tone-green-light);
}

.layered-pagination[data-tone="gold"] {
    --pagination-tone-light: var(--tone-gold-light);
    --pagination-tone-mid: var(--tone-gold-mid);
    --pagination-tone-dark: var(--tone-gold-dark);
    --pagination-focus: var(--tone-gold-light);
}

.layered-pagination__list {
    display: flex;
    align-items: center;
    gap: var(--pagination-gap);
    box-sizing: border-box;
    width: max-content;
    max-width: 100%;
    margin: 0;
    padding: 3px;
    overflow-x: auto;
    overflow-y: hidden;
    border: 1px solid var(--control-trench);
    border-radius: var(--control-radius-inner);
    background: var(--input-surface-bg-bottom);
    box-shadow: inset 0 2px 3px rgb(0 0 0 / 52%);
    list-style: none;
    overscroll-behavior-inline: contain;
    scrollbar-color: color-mix(in srgb, var(--pagination-tone-light) 32%, var(--control-shell-border)) var(--control-trench);
    scrollbar-width: thin;
}

.layered-pagination__item {
    display: flex;
    flex: 0 0 auto;
    margin: 0;
    padding: 0;
}

.layered-pagination__link,
.layered-pagination__ellipsis {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    box-sizing: border-box;
    min-width: var(--pagination-control-size);
    height: var(--pagination-control-size);
    padding-inline: 6px;
    border: 1px solid transparent;
    border-radius: 3px;
    font-size: var(--pagination-font-size);
    font-variant-numeric: tabular-nums;
    font-weight: 700;
    line-height: 1;
    text-decoration: none;
    white-space: nowrap;
}

.layered-pagination__link {
    background: transparent;
    color: var(--color-text-muted);
    cursor: pointer;
    transition:
        border-color var(--duration-fast) var(--ease-control),
        background var(--duration-fast) var(--ease-control),
        box-shadow var(--duration-fast) var(--ease-control),
        color var(--duration-fast) var(--ease-control);
}

.layered-pagination__link:hover {
    border-color: rgb(255 255 255 / 6%);
    background: rgb(255 255 255 / 4%);
    color: var(--color-text);
}

.layered-pagination__link[data-current="true"] {
    border-color: color-mix(in srgb, var(--pagination-tone-light) 46%, var(--control-shell-border));
    background:
        linear-gradient(180deg,
            color-mix(in srgb, var(--pagination-tone-light) 24%, var(--control-shell-top)) 0%,
            color-mix(in srgb, var(--pagination-tone-dark) 42%, var(--control-shell-bottom)) 100%);
    color: color-mix(in srgb, var(--pagination-tone-light) 88%, var(--color-text));
    box-shadow:
        inset 0 0 0 1px color-mix(in srgb, var(--pagination-tone-light) 12%, transparent),
        inset 0 1px rgb(255 255 255 / 8%),
        0 1px 2px rgb(0 0 0 / 34%);
}

.layered-pagination__link:focus-visible {
    outline: none;
    box-shadow: inset 0 0 0 2px var(--pagination-focus);
}

.layered-pagination__link[data-current="true"]:focus-visible {
    box-shadow:
        inset 0 0 0 2px var(--pagination-focus),
        inset 0 1px rgb(255 255 255 / 8%),
        0 1px 2px rgb(0 0 0 / 34%);
}

.layered-pagination__link[data-disabled="true"] {
    background: transparent;
    color: var(--color-text-muted);
    cursor: default;
    opacity: 0.42;
}

.layered-pagination__link[data-disabled="true"]:hover {
    border-color: transparent;
    background: transparent;
    color: var(--color-text-muted);
}

.layered-pagination__direction {
    gap: 7px;
    min-width: auto;
    padding-inline: var(--pagination-direction-padding);
    border-color: rgb(255 255 255 / 3%);
    background: rgb(255 255 255 / 2%);
}

.layered-pagination__ellipsis {
    color: var(--color-text-muted);
    letter-spacing: 0.08em;
}

.layered-pagination__chevron {
    display: block;
    width: 6px;
    height: 6px;
    border-block-start: 1.5px solid currentColor;
    border-inline-start: 1.5px solid currentColor;
}

.layered-pagination__chevron--previous {
    transform: rotate(-45deg);
}

.layered-pagination__chevron--next {
    transform: rotate(135deg);
}

@media (max-width: 520px) {
    .layered-pagination {
        --pagination-control-size: 28px;
        --pagination-font-size: 0.6875rem;
        --pagination-gap: 2px;
    }

    .layered-pagination__direction {
        min-width: var(--pagination-control-size);
        padding-inline: 6px;
    }

    .layered-pagination__direction-label {
        display: none;
    }
}

@media (forced-colors: active) {
    .layered-pagination,
    .layered-pagination__list,
    .layered-pagination__link,
    .layered-pagination__ellipsis {
        border-color: CanvasText;
        background: Canvas;
        color: CanvasText;
        box-shadow: none;
    }

    .layered-pagination__link[data-current="true"] {
        outline: 2px solid Highlight;
        outline-offset: -3px;
    }

    .layered-pagination__link[data-disabled="true"] {
        color: GrayText;
    }
}
